import { and, desc, eq } from "drizzle-orm";
import { getDb } from "../../../db";
import * as s from "../../../db/schema";

type Actor={email:string;displayName:string;role:string;organizationId:string};
const id=(prefix:string)=>`${prefix}-${Date.now().toString(36).toUpperCase()}${crypto.randomUUID().slice(0,4).toUpperCase()}`;
const allowed=(actor:Actor,roles:string[])=>roles.includes(actor.role)||actor.role==="admin";
async function actorFor(request:Request):Promise<{db:Awaited<ReturnType<typeof getDb>>,actor:Actor}>{
  const db=await getDb();
  let email=request.headers.get("oai-authenticated-user-email")?.trim().toLowerCase();
  const raw=request.headers.get("oai-authenticated-user-full-name");
  const name=raw&&request.headers.get("oai-authenticated-user-full-name-encoding")==="percent-encoded-utf-8"?decodeURIComponent(raw):email;
  if(!email&&process.env.NODE_ENV!=="production")email="demo@sovereign.local";
  if(!email)throw new Error("AUTH_REQUIRED");
  let user=await db.select().from(s.users).where(eq(s.users.email,email)).get();
  if(!user){const existing=await db.select().from(s.users).limit(1);if(existing.length)throw new Error("ACCESS_DENIED");await db.insert(s.organizations).values({id:"org-sovereign",name:"Sovereign Founding Institution",slug:"sovereign-founding"}).onConflictDoNothing();const [created]=await db.insert(s.users).values({email,displayName:name||email,role:"admin",organizationId:"org-sovereign"}).returning();user=created}
  if(user.status!=="active")throw new Error("ACCESS_DENIED");
  return{db,actor:{email:user.email,displayName:user.displayName,role:user.role,organizationId:user.organizationId}};
}
async function audit(db:Awaited<ReturnType<typeof getDb>>,actor:Actor,request:Request,action:string,entityType:string,entityCode:string,details:string){
  const prior=await db.select().from(s.auditEvents).where(eq(s.auditEvents.organizationId,actor.organizationId)).orderBy(desc(s.auditEvents.id)).limit(1);
  const previousHash=prior[0]?.eventHash??"GENESIS";const payload=`${previousHash}|${actor.email}|${action}|${entityType}|${entityCode}|${details}|${new Date().toISOString()}`;const bytes=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(payload));const eventHash=Array.from(new Uint8Array(bytes)).map(b=>b.toString(16).padStart(2,"0")).join("");
  await db.insert(s.auditEvents).values({organizationId:actor.organizationId,actorEmail:actor.email,actorRole:actor.role,action,entityType,entityCode,details,sourceIp:request.headers.get("x-forwarded-for"),previousHash,eventHash});
}
function fail(error:unknown){const message=error instanceof Error?error.message:"Request failed";const status=message==="AUTH_REQUIRED"?401:message==="ACCESS_DENIED"?403:400;return Response.json({error:message},{status})}

